const locales=['en-IN','hi-IN','mr-IN','ta-IN','te-IN'];let languageIndex=0;const originalText=new WeakMap();const originalAttributes=new WeakMap();const ordered=translations.slice().sort((a,b)=>b[0].length-a[0].length);const escaped=s=>s.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');const pattern=new RegExp(ordered.map(r=>escaped(r[0])).join('|'),'g');const lookup=new Map(translations.map(r=>[r[0],r]));function translateString(s){return languageIndex?s.replace(pattern,key=>lookup.get(key)[languageIndex]):s}
function translateUI(){const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);let node;while(node=walker.nextNode()){if(['SCRIPT','STYLE'].includes(node.parentElement?.tagName)||node.parentElement?.closest('[data-no-translate]'))continue;let record=originalText.get(node);if(!record||node.nodeValue!==record.last)record={source:node.nodeValue};const value=translateString(record.source);if(node.nodeValue!==value)node.nodeValue=value;record.last=value;originalText.set(node,record)}document.querySelectorAll('[placeholder],[aria-label],[title]').forEach(el=>{let records=originalAttributes.get(el)||{};for(const attr of ['placeholder','aria-label','title']){if(!el.hasAttribute(attr))continue;let r=records[attr];if(!r||el.getAttribute(attr)!==r.last)r={source:el.getAttribute(attr)};r.last=translateString(r.source);if(el.getAttribute(attr)!==r.last)el.setAttribute(attr,r.last);records[attr]=r}originalAttributes.set(el,records)})}
