function setLanguage(){if(recognition)recognition.stop();languageIndex=Math.max(0,locales.indexOf($('#language').value));document.documentElement.lang=locales[languageIndex].split('-')[0];document.title='VocalVend — '+translateString('Your local market.');$('#voiceStatus').textContent='Speak or type in your language. Your next order starts here.';translateUI();try{localStorage.setItem('vv-language',$('#language').value)}catch{}}
